# ---------------- polyfills (class-1, value-model) ----------------
#
# Not a transpile of any single Rust line: these implement Rust's
# fixed-width unsigned-integer wrapping semantics, which the type system
# gives for free in Rust and Python does not. UNIFORM policy: every
# arithmetic node in a u8-typed expression is wrapped in u8(), with no
# exemptions, so an unwrapped node is unambiguously a bug rather than a
# possibly-intentional omission (see module docstring).

def u8(x: int) -> int:
    return x & 0xFF


def u32(x: int) -> int:
    return x & 0xFFFFFFFF


def i8(x: int) -> int:
    """`as i8` cast: reduce mod 256 into Python's signed-friendly range."""
    x &= 0xFF
    return x - 256 if x >= 128 else x


# ---------------- api.rs ----------------

class CodeSink:
    """Transpiled from api.rs: `impl CodeSink for Vec<u8>` -- the crate's
    own reference CodeSink used for testing. Vec<u8> becomes a
    bytearray; `.bytes()` is added scaffolding (Rust's Vec<u8> IS the
    buffer, so no equivalent accessor exists to transpile -- same kind of
    templated boilerplate as the `__init__` transpile_vocab.py
    synthesizes from struct fields, not a literal source line).

    CUT: `use_target`/`known_offset` (api.rs) are RIP-relative-relocation
    and known-offset plumbing, reachable only from the Amode path --
    unreachable while GprMem::Mem stays cut. `add_trap` IS transpiled: the
    Vec<u8> reference impl is a literal no-op (`fn add_trap(&mut self, _:
    TrapCode) {}`), matched here exactly.
    """
    def __init__(self):
        self.buf = bytearray()

    def put1(self, b): self.buf.append(u8(b))

    def put2(self, v):
        v &= 0xFFFF
        self.buf += bytes((v & 0xFF, (v >> 8) & 0xFF))

    def put4(self, v):
        v = u32(v)
        self.buf += v.to_bytes(4, "little")

    def put8(self, v):
        self.buf += (v & 0xFFFFFFFFFFFFFFFF).to_bytes(8, "little")

    def add_trap(self, code):
        """api.rs: `fn add_trap(&mut self, _: TrapCode) {}` -- literal no-op."""
        pass

    def bytes(self): return bytes(self.buf)


# ---------------- rex.rs ----------------

def encode_modrm(m0d, enc_reg_g, rm_e):
    assert (m0d < 4)
    assert (enc_reg_g < 8)
    assert (rm_e < 8)
    return u8(u8((u8((u8(m0d & 3)) << 6)) | (u8((u8(enc_reg_g & 7)) << 3))) | (u8(rm_e & 7)))


def encode_sib(scale, enc_index, enc_base):
    assert (scale < 4)
    assert (enc_index < 8)
    assert (enc_base < 8)
    return u8(u8((u8((u8(scale & 3)) << 6)) | (u8((u8(enc_index & 7)) << 3))) | (u8(enc_base & 7)))


def is_special_if_8bit(enc):
    return ((enc >= 4) and (enc <= 7))


class RexPrefix:
    """Transpiled from rex.rs: RexPrefix (struct + impl)."""
    __slots__ = ("byte", "must_emit")

    def __init__(self, byte, must_emit):
        self.byte, self.must_emit = byte, must_emit

    @staticmethod
    def one_op(enc, w_bit, uses_8bit):
        must_emit = (uses_8bit and is_special_if_8bit(enc))
        w = 1 if w_bit else 0
        r = 0
        x = 0
        b = u8((u8(enc >> 3)) & 1)
        flag = u8(u8(u8(u8(0x40 | (u8(w << 3))) | (u8(r << 2))) | (u8(x << 1))) | b)
        return RexPrefix(byte=flag, must_emit=must_emit)

    @staticmethod
    def two_op(enc_reg, enc_rm, w_bit, uses_8bit):
        ret = RexPrefix.mem_op(enc_reg, enc_rm, w_bit, uses_8bit)
        if (uses_8bit and is_special_if_8bit(enc_rm)):
            ret.must_emit = True
        return ret

    @staticmethod
    def mem_op(enc_reg, enc_rm, w_bit, uses_8bit):
        must_emit = (uses_8bit and is_special_if_8bit(enc_reg))
        w = 1 if w_bit else 0
        r = u8((u8(enc_reg >> 3)) & 1)
        x = 0
        b = u8((u8(enc_rm >> 3)) & 1)
        flag = u8(u8(u8(u8(0x40 | (u8(w << 3))) | (u8(r << 2))) | (u8(x << 1))) | b)
        return RexPrefix(byte=flag, must_emit=must_emit)

    @staticmethod
    def with_digit(digit, enc_reg, w_bit, uses_8bit):
        return RexPrefix.two_op(digit, enc_reg, w_bit, uses_8bit)

    @staticmethod
    def three_op(enc_reg, enc_index, enc_base, w_bit, uses_8bit):
        must_emit = (uses_8bit and is_special_if_8bit(enc_reg))
        w = 1 if w_bit else 0
        r = u8((u8(enc_reg >> 3)) & 1)
        x = u8((u8(enc_index >> 3)) & 1)
        b = u8((u8(enc_base >> 3)) & 1)
        flag = u8(u8(u8(u8(0x40 | (u8(w << 3))) | (u8(r << 2))) | (u8(x << 1))) | b)
        return RexPrefix(byte=flag, must_emit=must_emit)

    def encode(self, sink):
        if ((self.byte != 0x40) or self.must_emit):
            sink.put1(self.byte)


