class Mem:
    """mem.rs: the `Amode` memory-operand payload of GprMem::Mem/XmmMem::Mem.

    CUT + REACHABILITY INVARIANT: the full Amode struct and its ModRM/SIB/
    displacement arithmetic (mem.rs emit_modrm_sib_disp, Disp, Scale,
    AmodeOffset*, rex.rs Disp) are NOT transpiled. They are unreachable
    while every caller constructs register operands -- true for all current
    slices (register allocation with spills is not cut). The invariant
    is asserted below, not assumed: if a Mem operand ever arrives with
    real field data, this raises loudly instead of emitting wrong bytes.
    """
    __slots__ = ("_trap",)

    def __init__(self, trap=None):
        self._trap = trap

    def trap_code(self):
        return self._trap

    def as_rex_prefix(self, *_a, **_k):
        raise NotImplementedError(
            "GprMem::Mem.as_rex_prefix not cut (Amode encoding). Invariant "
            "'all callers use register operands' has been violated.")

    def encode_bx_regs(self, *_a, **_k):
        raise NotImplementedError(
            "GprMem::Mem.encode_bx_regs not cut (Amode encoding). Invariant "
            "'all callers use register operands' has been violated.")

    def encode_rex_suffixes(self, *_a, **_k):
        raise NotImplementedError(
            "GprMem::Mem.encode_rex_suffixes not cut (Amode encoding). Invariant "
            "'all callers use register operands' has been violated.")


class GprMem:
    """Transpiled from mem.rs: enum GprMem<R, M> { Gpr(R), Mem(Amode<M>) }.

    Each match in the Rust impl (below) has exactly two arms: `Gpr(x)`
    dispatches to a method of the same name already defined on Gpr
    (gpr.rs transpile, citing the exact mem.rs match arm each one
    replaces); `Mem(amode)` dispatches to the identically-named method on
    the Mem class above, which raises per its own cut invariant. This
    turns a match-per-call-site into ordinary polymorphism -- the same
    refactor for every method, so it is applied uniformly rather than
    once by hand.
    """
    __slots__ = ("value",)

    def __init__(self, value):
        self.value = value if isinstance(value, (Gpr, Mem)) else Gpr(value)

    def _require_gpr(self):
        if isinstance(self.value, Mem):
            raise NotImplementedError(
                "GprMem::Mem arm not cut (Amode encoding). Invariant "
                "'all callers use register operands' has been violated.")
        return self.value

    def trap_code(self):
        return self.value.trap_code()

    def as_rex_prefix(self, enc_reg, has_w_bit, uses_8bit):
        """mem.rs GprMem::as_rex_prefix -- delegates to Gpr.as_rex_prefix (Gpr arm) or
        Mem.as_rex_prefix (Mem arm, cut) via polymorphism; see class docstring."""
        return self.value.as_rex_prefix(enc_reg, has_w_bit, uses_8bit)

    def encode_rex_suffixes(self, sink, enc_reg, bytes_at_end, evex_scaling):
        """mem.rs GprMem::encode_rex_suffixes -- delegates to Gpr.encode_rex_suffixes (Gpr arm) or
        Mem.encode_rex_suffixes (Mem arm, cut) via polymorphism; see class docstring."""
        return self.value.encode_rex_suffixes(sink, enc_reg, bytes_at_end, evex_scaling)

    def encode_bx_regs(self):
        """mem.rs GprMem::encode_bx_regs -- delegates to Gpr.encode_bx_regs (Gpr arm) or
        Mem.encode_bx_regs (Mem arm, cut) via polymorphism; see class docstring."""
        return self.value.encode_bx_regs()


# xmm.rs's XmmMem<R, M> / Xmm<R> are structurally identical to
# GprMem<R, M> / Gpr<R> for every path encode() reaches (compare
# mem.rs's XmmMem impl to its GprMem impl above -- same bodies,
# `Xmm`/`Gpr` variant names aside). Transpiling them a second time
# would emit the same class twice; alias instead.
XmmMem = GprMem
Xmm = Gpr


