class _CutPrefix:
    @staticmethod
    def _cut(*_a, **_k):
        raise NotImplementedError(
            "VEX/EVEX prefix encoding not cut (SIMD path). Invariant "
            "'no AVX instruction is reached' has been violated.")

    two_op = three_op = _cut


VexPrefix = _CutPrefix
EvexPrefix = _CutPrefix



# ---------------- imm.rs ----------------

class Imm:
    """Merged transpile of imm.rs Imm8/Imm16/Imm32/Imm64/Simm8/Simm16/Simm32.

    MERGE, not a guess: each of those seven `encode(&self, sink)` bodies
    is exactly `sink.putN(self.0 [as uN]);` (verified above, at transpile
    time, before this class is emitted) -- one line, parameterised only
    by which `sink.putN` is called. Collapsing seven near-identical
    classes into one width-keyed dispatch is the same kind of mechanical
    reduction as aliasing XmmMem to GprMem.
    """
    __slots__ = ("value", "width")

    def __init__(self, value, width=4):
        self.value, self.width = int(value), width

    def encode(self, sink):
        {1: sink.put1, 2: sink.put2, 4: sink.put4,
         8: sink.put8}[self.width](self.value)

    def trap_code(self):
        """Not a literal imm.rs line: an immediate never traps. Synthesized
        for interface uniformity with Gpr/GprMem/Mem (all reachable operand
        types present `.trap_code()`).
        """
        return None


