class _CustomEncode:
    """Transpiled from custom.rs: pub mod encode (the generated file's escape
    hatch for instructions assembler-x64-meta cannot template).

    CUT: `pub mod mnemonic`, `pub mod display`, `pub mod visit` in the same
    file are, respectively, mnemonic-string, Display/fmt, and
    RegisterVisitor (register-allocation) code -- none reachable from
    encode(). Handling every put1/put2/put4/put8 call uniformly here is
    exactly the fix for the bug the differential test caught: an earlier
    hand extraction matched only put1 and silently dropped put2/put4,
    under-emitting nop_5b..nop_9b by 2-4 bytes.
    """
    @staticmethod
    def nop_1b(_inst, buf):
        buf.put1(0x90)
    @staticmethod
    def nop_2b(_inst, buf):
        buf.put1(0x66)
        buf.put1(0x90)
    @staticmethod
    def nop_3b(_inst, buf):
        buf.put1(0x0F)
        buf.put1(0x1F)
        buf.put1(0x00)
    @staticmethod
    def nop_4b(_inst, buf):
        buf.put1(0x0F)
        buf.put1(0x1F)
        buf.put1(0x40)
        buf.put1(0x00)
    @staticmethod
    def nop_5b(_inst, buf):
        buf.put1(0x0F)
        buf.put1(0x1F)
        buf.put1(0x44)
        buf.put2(0x0000)
    @staticmethod
    def nop_6b(_inst, buf):
        buf.put1(0x66)
        buf.put1(0x0F)
        buf.put1(0x1F)
        buf.put1(0x44)
        buf.put2(0x0000)
    @staticmethod
    def nop_7b(_inst, buf):
        buf.put1(0x0F)
        buf.put1(0x1F)
        buf.put1(0x80)
        buf.put4(0x00000000)
    @staticmethod
    def nop_8b(_inst, buf):
        buf.put1(0x0F)
        buf.put1(0x1F)
        buf.put1(0x84)
        buf.put1(0x00)
        buf.put4(0x00000000)
    @staticmethod
    def nop_9b(_inst, buf):
        buf.put1(0x66)
        buf.put1(0x0F)
        buf.put1(0x1F)
        buf.put1(0x84)
        buf.put1(0x00)
        buf.put4(0x00000000)

custom_encode = _CustomEncode()
